"use client";
import { useRouter } from "next/navigation";
import { useState, useEffect, FormEvent } from "react";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import Skeleton from "@/components/Skeleton";
import { apiGet, apiPost, apiPut, apiDelete, getStoredAuth, extractItems } from "@/lib/api";

interface Alert {
  id: string;
  instrument_id: string;
  symbol: string;
  alert_type: string;
  condition: Record<string, unknown>;
  channels: string[];
  enabled: boolean;
  triggered_count: number;
  last_triggered: string | null;
  description: string;
  created_at: string;
}

const ALERT_TYPES = [
  { value: "price_above", label: "قیمت بالاتر از" },
  { value: "price_below", label: "قیمت پایین‌تر از" },
  { value: "volume_above", label: "حجم بالاتر از" },
  { value: "rsi_oversold", label: "RSI اشباع فروش" },
  { value: "rsi_overbought", label: "RSI اشباع خرید" },
  { value: "cross_above_sma", label: "عبور از میانگین به بالا" },
  { value: "cross_below_sma", label: "عبور از میانگین به پایین" },
];

const SYMBOLS = ["فولاد", "فملی", "شپنا", "وبانک", "خودرو", "ذوب", "رمپنا", "اخابر"];

export default function AlertsPage() {
  const router = useRouter();
  const auth = getStoredAuth();
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [symbol, setSymbol] = useState("فولاد");
  const [alertType, setAlertType] = useState("price_above");
  const [threshold, setThreshold] = useState("1000");
  const [description, setDescription] = useState("");
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (!auth) { router.push("/auth/login"); return; }
    fetchAlerts();
  }, []);

  async function fetchAlerts() {
    try {
      const data = await apiGet<unknown>("/alerts?page_size=50", auth?.token);
      setAlerts(extractItems<Alert>(data));
    } catch (error) {
      console.error("Error fetching alerts:", error);
    }
    setLoading(false);
  }

  async function handleCreate(e: FormEvent) {
    e.preventDefault();
    setError(""); setMessage("");
    try {
      const condition: Record<string, unknown> = { threshold: parseFloat(threshold), operator: "gte", field: "price" };
      if (alertType.includes("rsi")) condition.field = "rsi";
      if (alertType.includes("volume")) condition.field = "volume";
      if (alertType.includes("below")) condition.operator = "lte";
      if (alertType.includes("oversold")) { condition.field = "rsi"; condition.operator = "lte"; condition.threshold = 30; }
      if (alertType.includes("overbought")) { condition.field = "rsi"; condition.operator = "gte"; condition.threshold = 70; }

      await apiPost("/alerts", {
        instrument_id: symbol,
        symbol,
        alert_type: alertType,
        condition,
        channels: ["email", "console"],
        description,
      }, auth?.token);
      setMessage("هشدار با موفقیت ایجاد شد");
      setShowForm(false);
      fetchAlerts();
    } catch (err) { setError(err instanceof Error ? err.message : String(err)); }
  }

  async function toggleAlert(alert: Alert) {
    try {
      await apiPut(`/alerts/${alert.id}`, { enabled: !alert.enabled }, auth?.token);
      fetchAlerts();
    } catch {}
  }

  async function deleteAlert(id: string) {
    try {
      await apiDelete(`/alerts/${id}`, auth?.token);
      fetchAlerts();
    } catch {}
  }

  return (
    <AppLayout title="هشدارها">
        <div className="flex items-center justify-between mb-6">
          <button onClick={() => setShowForm(!showForm)} className="bg-primary-600 hover:bg-primary-500 text-white rounded-lg px-4 py-2 text-sm font-medium transition">
            {showForm ? "بستن" : "هشدار جدید"}
          </button>
        </div>

        {message && <div className="bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 px-4 py-2 rounded-lg mb-4 text-sm">{message}</div>}
        {error && <div className="bg-rose-500/10 border border-rose-500/30 text-rose-400 px-4 py-2 rounded-lg mb-4 text-sm">{error}</div>}

        {showForm && (
          <div className="glass-card p-6 mb-6">
            <h2 className="text-lg font-semibold mb-4">هشدار جدید</h2>
            <form onSubmit={handleCreate} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm text-gray-400 mb-1">نماد</label>
                  <select value={symbol} onChange={(e) => setSymbol(e.target.value)} className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2 text-white">
                    {SYMBOLS.map((s) => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm text-gray-400 mb-1">نوع هشدار</label>
                  <select value={alertType} onChange={(e) => setAlertType(e.target.value)} className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2 text-white">
                    {ALERT_TYPES.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm text-gray-400 mb-1">آستانه (Threshold)</label>
                  <input type="number" value={threshold} onChange={(e) => setThreshold(e.target.value)} className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2 text-white" />
                </div>
                <div>
                  <label className="block text-sm text-gray-400 mb-1">توضیحات</label>
                  <input type="text" value={description} onChange={(e) => setDescription(e.target.value)} className="w-full bg-surface-800 border border-surface-700 rounded-lg px-4 py-2 text-white" placeholder="اختیاری" />
                </div>
              </div>
              <button type="submit" className="bg-primary-600 hover:bg-primary-500 text-white rounded-lg px-6 py-2 text-sm font-medium transition">ایجاد هشدار</button>
            </form>
          </div>
        )}

         {loading ? (
           <div className="space-y-3">
             <Skeleton className="h-16 w-full rounded-xl" />
             <Skeleton className="h-16 w-full rounded-xl" />
             <Skeleton className="h-16 w-full rounded-xl" />
             <Skeleton className="h-16 w-full rounded-xl" />
           </div>
         ) : alerts.length === 0 ? (
          <div className="glass-card p-12 text-center">
            <p className="text-gray-500 text-lg mb-2">هیچ هشداری تعریف نشده</p>
            <p className="text-gray-600 text-sm">روی دکمه "هشدار جدید" کلیک کنید تا اولین هشدار خود را ایجاد کنید</p>
          </div>
        ) : (
          <div className="space-y-3">
            {alerts.map((alert) => (
              <div key={alert.id} className="glass-card p-4 flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <button onClick={() => toggleAlert(alert)} className={`w-10 h-6 rounded-full transition relative ${alert.enabled ? "bg-emerald-600" : "bg-surface-700"}`}>
                    <span className={`absolute top-0.5 w-5 h-5 rounded-full bg-white transition ${alert.enabled ? "left-0.5" : "right-0.5"}`} />
                  </button>
                  <div>
                    <p className="font-medium">{alert.symbol} — {ALERT_TYPES.find(t => t.value === alert.alert_type)?.label || alert.alert_type}</p>
                    <p className="text-xs text-gray-500">آستانه: {alert.condition?.threshold || "-"} | فعال‌سازی: {alert.triggered_count} بار</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <span className={`text-xs px-2 py-0.5 rounded-full ${alert.enabled ? "bg-emerald-500/10 text-emerald-400" : "bg-surface-700 text-gray-500"}`}>
                    {alert.enabled ? "فعال" : "غیرفعال"}
                  </span>
                  <button onClick={() => deleteAlert(alert.id)} className="text-rose-400 hover:text-rose-300 text-sm">حذف</button>
                </div>
              </div>
            ))}
          </div>
        )}
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import Skeleton from "@/components/Skeleton";
import { apiGet } from "@/lib/api";

interface AlphaStrategy {
  id: string;
  name: string;
  version: string;
  sharpe: number;
  returns: number;
  volatility: number;
  maxDrawdown: number;
  winRate: number;
  trades: number;
  status: "active" | "paper" | "disabled";
  description: string;
}

export default function AlphaPage() {
  const [filter, setFilter] = useState<"all" | "active" | "paper" | "disabled">("all");

  const { data: alphas, isLoading } = useQuery({
    queryKey: ["alpha-strategies"],
    queryFn: async () => {
      // Assuming an endpoint /api/v1/alpha’s exists or using fallback
      try {
        const data = await apiGet<Record<string, unknown>>('/alpha');
        return data || [];
      } catch {}
      return [
        { id: "mom-v3", name: "Momentum", version: "v3", sharpe: 2.14, returns: 34.5, volatility: 12.8, maxDrawdown: -8.2, winRate: 62, trades: 342, status: "active", description: "استراتژی مومنتوم بر اساس شتاب قیمتی ۳۰ روزه" },
        { id: "mr-v2", name: "Mean Reversion", version: "v2", sharpe: 1.87, returns: 28.2, volatility: 15.1, maxDrawdown: -11.5, winRate: 58, trades: 891, status: "active", description: "بازگشت به میانگین بر اساس انحراف از میانگین متحرک" },
        { id: "qi-v1", name: "Queue Imbalance", version: "v1", sharpe: 0.92, returns: 12.4, volatility: 18.6, maxDrawdown: -22.1, winRate: 51, trades: 56, status: "paper", description: "تحلیل عدم تعادل صف‌های خرید و فروش" },
        { id: "ml-v5", name: "ML Alpha", version: "v5", sharpe: 2.43, returns: 41.8, volatility: 14.2, maxDrawdown: -9.8, winRate: 65, trades: 1204, status: "active", description: "مدل یادگیری ماشین ترکیبی با ویژگی‌های تکنیکال و بنیادی" },
      ];
    },
  });

  const filtered = alphas?.filter((a: AlphaStrategy) => filter === "all" || a.status === filter);

  return (
    <AppLayout title="استراتژی‌های آلفا" subtitle="مدیریت و مانیتورینگ استراتژی‌های معاملاتی">
      <div className="flex gap-2 mb-4 flex-wrap">
        {([{ k: "all", l: "همه" }, { k: "active", l: "فعال" }, { k: "paper", l: "Paper" }, { k: "disabled", l: "غیرفعال" }] as const).map((t) => (
          <button key={t.k} onClick={() => setFilter(t.k)}
            className={`px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${filter === t.k ? "bg-primary-600 text-white" : "bg-surface-800 text-surface-400 hover:text-surface-200"}`}>{t.l}</button>
        ))}
      </div>

      <div className="grid gap-4">
        {isLoading ? (
          [1,2,3].map(i => <Skeleton key={i} className="h-40 w-full rounded-xl" />)
        ) : filtered?.map((a: AlphaStrategy) => (
          <div key={a.id} className="glass-card p-5">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-3">
                <h3 className="font-bold text-surface-200">{a.name} <span className="text-surface-500 text-xs font-mono">{a.version}</span></h3>
                <span className={`text-xs px-2 py-0.5 rounded-full ${
                  a.status === "active" ? "bg-accent-emerald/15 text-accent-emerald" :
                  a.status === "paper" ? "bg-accent-amber/15 text-accent-amber" :
                  "bg-surface-600/30 text-surface-400"
                }`}>{a.status === "active" ? "فعال" : a.status === "paper" ? "Paper" : "غیرفعال"}</span>
              </div>
              <span className="text-xs text-surface-400">{a.trades} معامله</span>
            </div>
            <p className="text-xs text-surface-400 mb-4">{a.description}</p>
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 text-center">
              <div className="bg-white/5 rounded-lg p-2">
                <div className={`text-sm font-bold font-mono ${a.sharpe > 1.5 ? "text-accent-emerald" : "text-accent-rose"}`}>{a.sharpe.toFixed(2)}</div>
                <div className="text-xs text-surface-500">Sharpe</div>
              </div>
              <div className="bg-white/5 rounded-lg p-2">
                <div className="text-sm font-bold font-mono text-accent-emerald">{a.returns.toFixed(1)}%</div>
                <div className="text-xs text-surface-500">بازده</div>
              </div>
              <div className="bg-white/5 rounded-lg p-2">
                <div className="text-sm font-bold font-mono text-accent-amber">{a.volatility.toFixed(1)}%</div>
                <div className="text-xs text-surface-500">نوسان</div>
              </div>
              <div className="bg-white/5 rounded-lg p-2">
                <div className="text-sm font-bold font-mono text-accent-rose">{a.maxDrawdown.toFixed(1)}%</div>
                <div className="text-xs text-surface-500">Max DD</div>
              </div>
              <div className="bg-white/5 rounded-lg p-2">
                <div className="text-sm font-bold font-mono text-accent-cyan">{a.winRate}%</div>
                <div className="text-xs text-surface-500">Win Rate</div>
              </div>
            </div>
          </div>
        )) || <div className="text-center py-12 text-surface-500">هیچ استراتژی یافت نشد</div>}
      </div>
    </AppLayout>
  );
}

"use client";

import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import dynamic from "next/dynamic";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import { generateCandleData } from "@/lib/types";
import Skeleton from "@/components/Skeleton";
import { apiGet } from "@/lib/api";

const CandleChartCard = dynamic(() => import("@/components/charts/CandleChartCard"), {
  ssr: false,
  loading: () => <div className="animate-pulse bg-surface-800/50 rounded-2xl" style={{ height: 400 }} />,
});


interface SentimentItem {
  date: string;
  score: number;
  label: string;
  volume: number;
}

interface TrendData {
  symbol: string;
  name: string;
  trend: "bullish" | "bearish" | "neutral";
  strength: number;
  gainers: { symbol: string; change: number }[];
  losers: { symbol: string; change: number }[];
}

interface Recommendation {
  symbol: string;
  name: string;
  signal: "buy" | "hold" | "sell";
  targetPrice: number;
  currentPrice: number;
  upside: number;
  analyst: string;
}

interface ElliotWave {
  wave: number;
  label: string;
  status: "completed" | "in-progress" | "projected";
  priceRange: string;
}

interface LiquidityFlow {
  symbol: string;
  inflow: number;
  outflow: number;
  net: number;
  direction: "positive" | "negative" | "neutral";
}

type AnalysisTab = "sentiment" | "trends" | "recommendations" | "elliot" | "liquidity" | "technical";

const TABS: { key: AnalysisTab; label: string }[] = [
  { key: "sentiment", label: "تحلیل احساسات" },
  { key: "trends", label: "روندها" },
  { key: "recommendations", label: "توصیه‌ها" },
  { key: "technical", label: "تحلیل تکنیکال" },
  { key: "elliot", label: "امواج الیوت" },
  { key: "liquidity", label: "نقدینگی" },
];

function TrendIndicator({ value }: { value: number }) {
  const safeValue = Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0;
  return (
    <div className="flex items-center gap-2">
      <div className="w-32 h-2 bg-surface-700 rounded-full overflow-hidden">
        <div className="h-full rounded-full transition-all" style={{
          width: `${safeValue}%`,
          background: safeValue >= 60 ? "#22c55e" : safeValue >= 40 ? "#f59e0b" : "#ef4444"
        }} />
      </div>
      <span className={`text-xs font-mono ${safeValue >= 60 ? "text-accent-emerald" : safeValue >= 40 ? "text-accent-amber" : "text-accent-rose"}`}>
        {safeValue}%
      </span>
    </div>
  );
}

export default function AnalysisPage() {
  const [tab, setTab] = useState<AnalysisTab>("sentiment");
  const [elliotSymbol, setElliotSymbol] = useState("شاخص کل");

  const { data: analysis, isLoading } = useQuery({
    queryKey: ["analysis-full"],
    queryFn: async () => {
      try {
        return await apiGet<Record<string, unknown>>("/analysis/overview");
      } catch {}
      return null;
    },
    refetchInterval: 60000,
  });

  const avgSentiment = analysis?.sentiment?.length
    ? (analysis.sentiment.reduce((sum: number, s: SentimentItem) => sum + (Number(s.score) || 0), 0) / analysis.sentiment.length).toFixed(0)
    : null;

  const CANDLE_DATA = useMemo(() => generateCandleData(60), []);

  return (
    <AppLayout title="تحلیل بازار" subtitle="تحلیل‌های تکنیکال، فاندامنتال و احساسات بازار">
      <div className="flex gap-2 mb-6 flex-wrap">
        {TABS.map((t) => (
          <button key={t.key} onClick={() => setTab(t.key)}
            className={`px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${
              tab === t.key ? "bg-primary-600 text-white" : "bg-surface-800 text-surface-400 hover:text-surface-200"
            }`}>{t.label}</button>
        ))}
      </div>

      {isLoading ? (
          <div className="space-y-4">
            <Skeleton className="h-32 w-full rounded-2xl" />
            <Skeleton className="h-64 w-full rounded-2xl" />
          </div>
        ) : (
          <>
            {tab === "sentiment" && (
              <div className="space-y-4">
                <div className="glass-card p-5">
                  <h2 className="font-bold text-surface-200 mb-4">شاخص احساسات بازار</h2>
                  <div className="flex items-center gap-6 mb-4">
                    <div className="text-center">
                      <div className={`text-3xl font-black ${
                        avgSentiment === null ? "text-surface-600" :
                        Number(avgSentiment) >= 60 ? "text-accent-emerald" : Number(avgSentiment) >= 40 ? "text-accent-amber" : "text-accent-rose"
                      }`}>{avgSentiment !== null ? `${avgSentiment}%` : "—"}</div>
                      <div className="text-xs text-surface-500 mt-1">میانگین ۷ روزه</div>
                    </div>
                    <div className="flex-1">
                      {avgSentiment !== null ? (
                        <TrendIndicator value={Number(avgSentiment)} />
                      ) : (
                        <div className="w-full h-2 bg-surface-700 rounded-full" />
                      )}
                      <div className="flex justify-between text-xs text-surface-600 mt-1">
                        <span>منفی</span><span>خنثی</span><span>مثبت</span>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="glass-card p-5">
                  <h2 className="font-bold text-surface-200 mb-4">روند احساسات</h2>
                  <div className="overflow-x-auto">
                    <table className="w-full text-right text-sm">
                      <thead>
                        <tr className="text-surface-500 border-b border-surface-700">
                          <th className="pb-2 font-medium">تاریخ</th>
                          <th className="pb-2 font-medium">امتیاز</th>
                          <th className="pb-2 font-medium">وضعیت</th>
                          <th className="pb-2 font-medium">حجم معاملات</th>
                        </tr>
                      </thead>
                      <tbody>
                        {analysis?.sentiment?.map((s: SentimentItem, i: number) => (
                          <tr key={i} className="border-b border-surface-800/50">
                            <td className="py-2.5 text-surface-400 text-xs">{s.date || ""}</td>
                            <td className="py-2.5"><TrendIndicator value={Number(s.score) || 0} /></td>
                            <td className="py-2.5">
                              <span className={`text-xs px-2 py-0.5 rounded-full ${
                                s.label === "مثبت" ? "bg-accent-emerald/15 text-accent-emerald" :
                                s.label === "منفی" ? "bg-accent-rose/15 text-accent-rose" :
                                "bg-accent-amber/15 text-accent-amber"
                              }`}>{s.label || "خنثی"}</span>
                            </td>
                            <td className="py-2.5 font-mono text-surface-200 text-xs">{(s.volume || 0).toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}

            {tab === "trends" && (
              <div className="grid md:grid-cols-3 gap-4">
                <div className="glass-card p-5 col-span-2">
                  <h2 className="font-bold text-surface-200 mb-4">تحلیل روند بازار</h2>
                  <div className="space-y-3">
                    <div className="flex items-center justify-between py-2 px-3 bg-surface-800/50 rounded-lg">
                      <span className="text-sm text-surface-300">نشانگر</span>
                      <span className="text-sm text-surface-300">مقدار</span>
                    </div>
                    <div className="flex items-center justify-between py-2 px-3">
                      <span className="text-sm text-surface-400">روند کلی</span>
                      <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                        analysis?.trends?.trend === "bullish" ? "bg-accent-emerald/15 text-accent-emerald" :
                        analysis?.trends?.trend === "bearish" ? "bg-accent-rose/15 text-accent-rose" :
                        "bg-accent-amber/15 text-accent-amber"
                      }`}>{analysis?.trends?.trend === "bullish" ? "صعودی" : analysis?.trends?.trend === "bearish" ? "نزولی" : "خنثی"}</span>
                    </div>
                    <div className="flex items-center justify-between py-2 px-3">
                      <span className="text-sm text-surface-400">قدرت روند</span>
                      <TrendIndicator value={analysis?.trends?.strength || 0} />
                    </div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="glass-card p-5">
                    <h3 className="font-bold text-accent-emerald mb-3">پررشدترین‌ها</h3>
                    <div className="space-y-2">
                      {analysis?.trends?.gainers?.map((g: { symbol: string; change: number }) => (
                        <div key={g.symbol} className="flex items-center justify-between">
                          <span className="text-sm text-surface-200">{g.symbol}</span>
                          <span className="text-sm font-mono text-accent-emerald">+{g.change.toFixed(1)}%</span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="glass-card p-5">
                    <h3 className="font-bold text-accent-rose mb-3">پربازده‌ترین‌ها</h3>
                    <div className="space-y-2">
                      {analysis?.trends?.losers?.map((l: { symbol: string; change: number }) => (
                        <div key={l.symbol} className="flex items-center justify-between">
                          <span className="text-sm text-surface-200">{l.symbol}</span>
