                    </div>
                  ))}
                </div>

                {/* Pattern Detection */}
                <div className="glass-card p-5">
                  <h3 className="font-bold text-surface-200 mb-3">الگوهای شناسایی شده</h3>
                  <div className="space-y-2">
                    {[
                      { pattern: "چکش (Hammer)", symbol: "فولاد", confidence: "بالا", desc: "الگوی برگشتی صعودی در حمایت روزانه" },
                      { pattern: "انگلفینگ صعودی", symbol: "شپنا", confidence: "متوسط", desc: "الگوی دو شمعی برگشتی در انتهای روند نزولی" },
                      { pattern: "ستاره ثاقب", symbol: "وبملت", confidence: "پایین", desc: "الگوی هشدار در سقف مقاومت" },
                    ].map((p, i) => (
                      <div key={i} className="flex items-start gap-3 p-3 bg-surface-800/30 rounded-lg">
                        <span className="w-2 h-2 rounded-full mt-1.5" style={{
                          background: p.confidence === "بالا" ? "var(--positive)" : p.confidence === "متوسط" ? "var(--neutral)" : "var(--negative)"
                        }} />
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <span className="font-medium text-surface-200 text-sm">{p.pattern}</span>
                            <span className="text-xs text-primary-400">{p.symbol}</span>
                          </div>
                          <p className="text-xs text-surface-500 mt-1">{p.desc}</p>
                        </div>
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${
                          p.confidence === "بالا" ? "bg-accent-emerald/15 text-accent-emerald" :
                          p.confidence === "متوسط" ? "bg-accent-amber/15 text-accent-amber" :
                          "bg-accent-rose/15 text-accent-rose"
                        }`}>{p.confidence}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </>
        )}
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import Skeleton from "@/components/Skeleton";
import { apiPost, apiGet } from "@/lib/api";

interface Strategy {
  name: string;
  type: string;
  params: { name: string; type: string; default: unknown }[];
}

interface BacktestRun {
  id: string;
  name: string;
  status: string;
  progress_pct: number;
  message: string;
}

interface BacktestResult {
  id: string;
  name: string;
  status: string;
  total_return_pct: number;
  annualized_return_pct: number;
  sharpe_ratio: number;
  max_drawdown_pct: number;
  win_rate: number;
  total_trades: number;
  winning_trades: number;
  losing_trades: number;
  initial_capital: number;
  final_value: number;
  equity_curve: { timestamp: string; nav: number }[];
  trades: { instrument_id: string; side: string; quantity: number; price: number; pnl: number }[];
  metrics: Record<string, number>;
  completed_at: string;
}

// API is handled by apiGet/apiPost from @/lib/api
const SYMBOLS = ["فولاد", "شپنا", "وبملت", "خودرو", "فملی", "ذوب", "کگل", "چادر"];

export default function BacktestPage() {
  const [selectedResult, setSelectedResult] = useState<BacktestResult | null>(null);
  const [formData, setFormData] = useState({
    name: "بک‌تست جدید",
    symbols: ["فولاد"],
    strategyType: "moving_average_cross",
    startDate: (() => {
      const d = new Date(); d.setFullYear(d.getFullYear() - 1);
      return d.toISOString().split("T")[0];
    })(),
    endDate: new Date().toISOString().split("T")[0],
    capital: 1000000000,
  });

  const { data: strategies, isLoading: loadingStrats } = useQuery({
    queryKey: ["backtest-strategies"],
    queryFn: async () => {
      return await apiGet<Record<string, unknown>>('/backtests/strategies');
    },
  });

  const { data: runs, isLoading: loadingRuns } = useQuery({
    queryKey: ["backtest-runs"],
    queryFn: async () => {
      return await apiGet<Record<string, unknown>>('/backtests/runs');
    },
    refetchInterval: 5000,
  });

  const { data: result, isLoading: loadingResult } = useQuery({
    queryKey: ["backtest-result", selectedResult?.id],
    queryFn: async () => {
      if (!selectedResult?.id) return null;
      return await apiGet<Record<string, unknown>>(`/backtests/runs/${selectedResult.id}/result`);
    },
    enabled: !!selectedResult,
  });

  const runMutation = useMutation({
    mutationFn: async (data: Record<string, unknown>) => {
      return await apiPost<Record<string, unknown>>('/backtests/run', data);
    },
    onSuccess: () => {
      toast.success("بک‌تست با موفقیت شروع شد");
    },
    onError: (err: Error) => toast.error(err.message),
  });

  function formatRials(v: number) {
    return new Intl.NumberFormat("fa-IR").format(Math.round(v));
  }

  return (
    <AppLayout title="بک‌تست استراتژی">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 glass-card p-5">
            <h2 className="text-lg font-semibold text-gray-700 mb-4">تنظیمات بک‌تست</h2>

            <label className="block mb-2 text-sm text-gray-600">نام</label>
            <input className="w-full border rounded-lg px-3 py-2 mb-3 text-sm" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />

            <label className="block mb-2 text-sm text-gray-600">نمادها</label>
            <div className="flex flex-wrap gap-1 mb-3">
              {SYMBOLS.map(s => (
                <button key={s} onClick={() => setFormData(prev => ({...prev, symbols: prev.symbols.includes(s) ? prev.symbols.filter(x => x !== s) : [...prev.symbols, s]}))}
                  className={`px-3 py-1 text-xs rounded-full border ${formData.symbols.includes(s) ? "bg-blue-600 text-white border-blue-600" : "bg-gray-100 text-gray-600 border-gray-300"}`}>
                  {s}
                </button>
              ))}
            </div>

            <label className="block mb-2 text-sm text-gray-600">استراتژی</label>
            <select className="w-full border rounded-lg px-3 py-2 mb-3 text-sm" value={formData.strategyType} onChange={e => setFormData({...formData, strategyType: e.target.value})}>
              {strategies?.map((s: Record<string, unknown>) => (
                <option key={s.name} value={s.name}>{s.name}</option>
              ))}
            </select>

            <div className="grid grid-cols-2 gap-2 mb-3">
              <div>
                <label className="block mb-1 text-sm text-gray-600">از تاریخ</label>
                <input type="date" className="w-full border rounded-lg px-3 py-2 text-sm" value={formData.startDate} onChange={e => setFormData({...formData, startDate: e.target.value})} />
              </div>
              <div>
                <label className="block mb-1 text-sm text-gray-600">تا تاریخ</label>
                <input type="date" className="w-full border rounded-lg px-3 py-2 text-sm" value={formData.endDate} onChange={e => setFormData({...formData, endDate: e.target.value})} />
              </div>
            </div>

            <label className="block mb-2 text-sm text-gray-600">سرمایه اولیه (ریال)</label>
            <input type="number" className="w-full border rounded-lg px-3 py-2 mb-4 text-sm" value={formData.capital} onChange={e => setFormData({...formData, capital: Number(e.target.value)})} />

            <button onClick={() => runMutation.mutate({
              name: formData.name,
              symbols: formData.symbols,
              strategy_type: formData.strategyType,
              strategy_params: {},
              start_date: formData.startDate,
              end_date: formData.endDate,
              initial_capital: formData.capital,
            })} disabled={runMutation.isPending}
              className="w-full bg-blue-600 text-white py-2.5 rounded-lg font-medium hover:bg-blue-700 disabled:opacity-50">
              {runMutation.isPending ? "در حال اجرا..." : "اجرای بک‌تست"}
            </button>
          </div>

          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-xl shadow-sm p-5 border border-gray-100">
              <h2 className="text-lg font-semibold text-gray-700 mb-4">بک‌تست‌های انجام شده</h2>
              {loadingRuns ? (
                <div className="space-y-2">
                  {[1,2,3].map(i => <Skeleton key={i} className="h-16 w-full rounded-lg" />)}
                </div>
              ) : runs?.length === 0 ? (
                <p className="text-gray-400 text-sm">هنوز بک‌تستی اجرا نشده</p>
              ) : (
                <div className="space-y-2">
                  {runs?.map((run: Record<string, unknown>) => (
                    <div key={run.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                      <div>
                        <p className="font-medium text-gray-700">{run.name}</p>
                        <p className="text-xs text-gray-400">{run.status} — {run.progress_pct}%</p>
                      </div>
                      <button onClick={() => setSelectedResult({ id: String(run.id) } as BacktestResult)} className="text-blue-600 text-sm hover:underline">
                        مشاهده نتیجه
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {loadingResult ? (
              <Skeleton className="h-96 w-full rounded-2xl" />
            ) : result ? (
              <div className="bg-white rounded-xl shadow-sm p-5 border border-gray-100">
                <h2 className="text-lg font-semibold text-gray-700 mb-4">نتیجه بک‌تست: {result.name}</h2>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                  {[
                    { label: "بازده کل", value: `${result.total_return_pct}%`, color: result.total_return_pct >= 0 ? "text-green-600" : "text-red-600" },
                    { label: "بازده سالانه", value: `${result.annualized_return_pct}%`, color: "text-gray-700" },
                    { label: "نسبت شارپ", value: result.sharpe_ratio.toFixed(2), color: result.sharpe_ratio >= 1 ? "text-green-600" : "text-yellow-600" },
                    { label: "بیشترین کاهش", value: `${result.max_drawdown_pct}%`, color: "text-red-600" },
                    { label: "درصد برندگی", value: `${result.win_rate}%`, color: result.win_rate >= 50 ? "text-green-600" : "text-red-600" },
                    { label: "تعداد معاملات", value: result.total_trades.toString(), color: "text-gray-700" },
                    { label: "سرمایه اولیه", value: `${formatRials(result.initial_capital)} ریال`, color: "text-gray-700" },
                    { label: "ارزش نهایی", value: `${formatRials(result.final_value)} ریال`, color: result.final_value >= result.initial_capital ? "text-green-600" : "text-red-600" },
                  ].map(item => (
                    <div key={item.label} className="bg-gray-50 rounded-lg p-3 text-center">
                      <p className="text-xs text-gray-500 mb-1">{item.label}</p>
                      <p className={`text-lg font-bold ${item.color}`}>{item.value}</p>
                    </div>
                  ))}
                </div>
                {/* ...Equity Curve and Trades table can be added here similarly to Portfolio page... */}
              </div>
            ) : null}
          </div>
        </div>
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import Skeleton from "@/components/Skeleton";
import { apiGet, extractArray } from "@/lib/api";

interface CodalCompany {
  code: string;
  name: string;
  industry: string;
  lastPrice: number;
  change: number;
  volume: number;
  marketCap: number;
  peRatio: number;
  eps: number;
  status: "active" | "inactive";
}

interface CompanyProfile {
  code: string;
  name: string;
  industry: string;
  subIndustry: string;
  website: string;
  established: string;
  employees: number;
  description: string;
}

interface FinancialReport {
  quarter: string;
  revenue: number;
  netProfit: number;
  eps: number;
  date: string;
}

interface DividendItem {
  date: string;
  perShare: number;
  total: number;
}

interface ShareholderItem {
  name: string;
  shares: number;
  percentage: number;
}

interface InsiderTrade {
  date: string;
  type: "buy" | "sell";
  count: number;
  price: number;
}

function formatPrice(n: number): string {
  return n.toLocaleString("fa-IR");
}

function formatLarge(n: number): string {
  if (n >= 1000000000000000) return (n / 1000000000000000).toFixed(1) + " همت";
  if (n >= 1000000000000) return (n / 1000000000000).toFixed(1) + " میلیارد";
  if (n >= 1000000000) return (n / 1000000000).toFixed(1) + " میلیارد";
  return formatPrice(n);
}

function formatVolume(n: number): string {
  if (n >= 1000000) return (n / 1000000).toFixed(1) + " میلیون";
  if (n >= 1000) return (n / 1000).toFixed(1) + " هزار";
  return formatPrice(n);
}

export default function CodalPage() {
  const [filter, setFilter] = useState<"all" | "active" | "inactive">("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCode, setSelectedCode] = useState<string | null>(null);

  const { data: companies, isLoading: loadingCompanies } = useQuery({
    queryKey: ["codal-companies"],
    queryFn: async () => {
      try {
        const response = await apiGet<unknown>("/codal");
        const items = extractArray<CodalCompany>(response);
        if (items.length > 0) return items;
      } catch {}
      return [
        { code: "فولاد", name: "فولاد مبارکه اصفهان", industry: "فلزات اساسی", lastPrice: 35840, change: 2.3, volume: 125000000, marketCap: 456000000000000, peRatio: 6.2, eps: 5780, status: "active" },
        { code: "شپنا", name: "پالایش نفت اصفهان", industry: "پالایشی", lastPrice: 12750, change: -1.5, volume: 89000000, marketCap: 215000000000000, peRatio: 4.8, eps: 2650, status: "active" },
      ];
    },
    refetchInterval: 60000,
  });

  const { data: detail, isLoading: loadingDetail } = useQuery({
    queryKey: ["codal-detail", selectedCode],
    queryFn: async () => {
      if (!selectedCode) return null;
      const [profile, financials, dividends, holders, insider] = await Promise.all([
        apiGet<CompanyProfile>(`/codal/${selectedCode}/profile`),
        apiGet<FinancialReport[]>(`/codal/${selectedCode}/financials`),
        apiGet<DividendItem[]>(`/codal/${selectedCode}/dividends`),
        apiGet<ShareholderItem[]>(`/codal/${selectedCode}/holders`),
        apiGet<InsiderTrade[]>(`/codal/${selectedCode}/insider`),
      ]);
      return { profile, financials, dividends, holders, insider };
    },
    enabled: !!selectedCode,
  });

  const filtered = companies?.filter((c: CodalCompany) => {
    if (filter === "active" && c.status !== "active") return false;
    if (filter === "inactive" && c.status !== "inactive") return false;
    if (searchQuery) {
      const q = searchQuery.trim();
      return c.code.includes(q) || c.name.includes(q);
    }
    return true;
  });

  const selectedCompany = selectedCode ? companies?.find((c: CodalCompany) => c.code === selectedCode) : null;

  return (
    <AppLayout title="اطلاعات شرکت‌ها (کدال)" subtitle="مشاهده اطلاعات شرکت‌های پذیرفته شده در بورس و فرابورس">
      <div className="flex flex-wrap items-center justify-between mb-6">
          <div>
            <h1 className="text-2xl font-bold text-surface-100">اطلاعات شرکت‌ها (کدال)</h1>
            <p className="text-sm text-surface-500 mt-1">مشاهده اطلاعات شرکت‌های پذیرفته شده در بورس و فرابورس</p>
          </div>
          <div className="flex items-center gap-2 mt-3 sm:mt-0">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="جستجوی نماد یا نام شرکت..."
              className="px-3 py-2 bg-surface-800 border border-surface-700 rounded text-surface-200 text-sm focus:outline-none focus:border-primary-500 w-56"
            />
            {loadingCompanies && <span className="w-2 h-2 rounded-full bg-accent-amber animate-pulse" />}
          </div>
        </div>

        <div className="flex gap-2 mb-4 flex-wrap">
          {["all", "active", "inactive"].map((key) => (
            <button key={key} onClick={() => setFilter(key as "all" | "active" | "inactive")}
              className={`px-4 py-1.5 rounded-lg text-xs font-medium transition-all ${
                filter === key ? "bg-primary-600 text-white" : "bg-surface-800 text-surface-400 hover:text-surface-200"
              }`}>{key === "all" ? "همه" : key === "active" ? "فعال" : "راکد"}</button>
          ))}
        </div>

        <div className="glass-card p-5 mb-6 overflow-x-auto">
          <table className="w-full text-right text-sm">
            <thead>
              <tr className="text-surface-500 border-b border-surface-700">
                <th className="pb-2 font-medium">کد</th>
                <th className="pb-2 font-medium">نام شرکت</th>
                <th className="pb-2 font-medium">صنعت</th>
                <th className="pb-2 font-medium">آخرین قیمت</th>
                <th className="pb-2 font-medium">تغییر</th>
                <th className="pb-2 font-medium">حجم</th>
                <th className="pb-2 font-medium">ارزش بازار</th>
                <th className="pb-2 font-medium">P/E</th>
                <th className="pb-2 font-medium">EPS</th>
                <th className="pb-2 font-medium">وضعیت</th>
              </tr>
            </thead>
            <tbody>
              {loadingCompanies ? (
                [1,2,3,4,5].map(i => <tr key={i} className="border-b border-surface-800/50"><td colSpan={10} className="py-4"><Skeleton className="h-4 w-full" /></td></tr>)
              ) : filtered?.map((c: CodalCompany) => (
                <tr key={c.code} onClick={() => setSelectedCode(selectedCode === c.code ? null : c.code)}
                  className={`border-b border-surface-800/50 hover:bg-white/5 cursor-pointer transition-all ${
                    selectedCode === c.code ? "bg-primary-600/10" : ""
                  }`}>
                  <td className="py-2.5 font-mono text-surface-200 font-bold">{c.code}</td>
                  <td className="py-2.5 text-surface-200">{c.name}</td>
                  <td className="py-2.5 text-surface-400 text-xs">{c.industry}</td>
                  <td className="py-2.5 font-mono text-surface-200">{formatPrice(c.lastPrice)}</td>
                  <td className={`py-2.5 font-mono ${c.change >= 0 ? "text-accent-emerald" : "text-accent-rose"}`}>
                    {c.change >= 0 ? "+" : ""}{c.change.toFixed(1)}%
                  </td>
                  <td className="py-2.5 font-mono text-surface-400 text-xs">{formatVolume(c.volume)}</td>
                  <td className="py-2.5 font-mono text-surface-200 text-xs">{formatLarge(c.marketCap)}</td>
                  <td className="py-2.5 font-mono text-surface-400">{c.peRatio > 0 ? c.peRatio.toFixed(1) : "—"}</td>
