// ── File Upload ──────────────────────────────────

function FileUploadSection({ onFilesAdded }: { onFilesAdded: (files: File[]) => void }) {
  const [dragOver, setDragOver] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const files = Array.from(e.dataTransfer.files).filter(f =>
      f.name.endsWith('.csv') || f.name.endsWith('.xlsx') || f.name.endsWith('.xls') || f.name.endsWith('.json')
    );
    if (files.length > 0) onFilesAdded(files);
  }, [onFilesAdded]);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      onFilesAdded(Array.from(e.target.files));
      e.target.value = '';
    }
  }, [onFilesAdded]);

  return (
    <div
      onDrop={handleDrop}
      onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
      onDragLeave={() => setDragOver(false)}
      onClick={() => inputRef.current?.click()}
      className={`border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all ${
        dragOver
          ? "border-primary-400 bg-primary-600/10 scale-[1.02]"
          : "border-surface-600 hover:border-primary-500/50 bg-surface-800/30"
      }`}
    >
      <input
        ref={inputRef}
        type="file"
        accept=".csv,.xlsx,.xls,.json"
        multiple
        onChange={handleFileInput}
        className="hidden"
      />
      <div className="text-4xl mb-3">{dragOver ? "📥" : "📄"}</div>
      <p className="text-surface-300 font-medium mb-1">
        {dragOver ? "فایل را رها کنید..." : "فایل را بکشید و رها کنید یا کلیک کنید"}
      </p>
      <p className="text-xs text-surface-500">
        فرمت‌های مجاز: CSV, Excel (.xlsx, .xls), JSON
      </p>
    </div>
  );
}

