                  { symbol: "کالا", price: "18,230", change: "+1.56%", isUp: true, volume: "1M" },
                  { symbol: "وغدیر", price: "19,450", change: "-2.10%", isUp: false, volume: "0.8M" },
                ].map((row) => (
                  <tr key={row.symbol}>
                    <td className="symbol">{row.symbol}</td>
                    <td className="value">{row.price}</td>
                    <td className={`value ${row.isUp === true ? "positive" : row.isUp === false ? "negative" : "neutral"}`}>{row.change}</td>
                    <td className="value">{row.volume}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>

        {/* Sentiment Trend Mini Chart */}
        <Card title="روند احساسات بازار">
          <SentimentChart data={sentimentData.slice(-15)} />
          <SSRSafe className="sentiment-stats" style={{ marginTop: 8 }}>
            <div className="sentiment-stat">
              <div className="sentiment-stat-label">مثبت</div>
              <div className="sentiment-stat-value positive-value">{sentimentData[sentimentData.length - 1]?.positive}%</div>
            </div>
            <div className="sentiment-stat">
              <div className="sentiment-stat-label">خنثی</div>
              <div className="sentiment-stat-value neutral-value">{sentimentData[sentimentData.length - 1]?.neutral}%</div>
            </div>
            <div className="sentiment-stat">
              <div className="sentiment-stat-label">منفی</div>
              <div className="sentiment-stat-value negative-value">{sentimentData[sentimentData.length - 1]?.negative}%</div>
            </div>
          </SSRSafe>
        </Card>

        {/* AI Insights */}
        <Card title="تحلیل هوش مصنوعی">
          <div className="ai-insights">
            {MOCK_INSIGHTS.map((insight, i) => (
              <div key={i} className="insight-item">
                <div className={`insight-icon ${insight.type}`}>
                  <span className="material-icons">{insight.icon}</span>
                </div>
                <div className="insight-content">
                  <div className="insight-title">{insight.title}</div>
                  <div className="insight-desc">{insight.description}</div>
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>

      {/* ── 🐞 Debug Panel ──────────────────────────────── */}
      <DebugPanel
        logs={logs}
        stats={stats}
        onClear={clearLogs}
        isEnabled={isEnabled}
        onToggle={toggleEnabled}
        onExport={() => {
          const dataStr = JSON.stringify(logs, null, 2);
          const blob = new Blob([dataStr], { type: "application/json" });
          const url = URL.createObjectURL(blob);
          const a = document.createElement("a");
          a.href = url;
          a.download = `debug-logs-${Date.now()}.json`;
          a.click();
          URL.revokeObjectURL(url);
        }}
      />
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import dynamic from "next/dynamic";
import AppLayout from "@/components/layout/AppLayout";
import { apiGet, apiPost, extractArray } from "@/lib/api";
import ClientOnly from "@/components/ClientOnly";

const EquityCurveChart = dynamic(() => import("@/components/charts/EquityCurveChart"), {
  ssr: false,
  loading: () => <div className="animate-pulse bg-surface-800/50 rounded-2xl" style={{ height: 256 }} />,
});

// ── تعریف تایپ‌ها ──────────────────────────────────────
interface Position {
  symbol: string;
  quantity: number;
  avg_cost: number;
  current_price: number;
  market_value: number;
  unrealized_pnl: number;
  weight_pct: number;
}

interface Portfolio {
  id: string;
  name: string;
  description: string;
  initial_capital: number;
  current_value: number;
  currency: string;
  positions: Position[];
}

interface PortfolioItem {
  id: string;
  name: string;
  current_value: number;
  total_return_pct: number;
}

interface PortfolioList {
  items: PortfolioItem[];
  total: number;
}

// ── کامپوننت اصلی ──────────────────────────────────────
export default function PortfolioPage() {
  const queryClient = useQueryClient();
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isCreating, setIsCreating] = useState(false);
  const [newPortfolioName, setNewPortfolioName] = useState("");

  const { data: portfolios, isLoading: loadingList } = useQuery({
    queryKey: ["portfolios"],
    queryFn: async (): Promise<PortfolioList> => {
      const response = await apiGet<Record<string, unknown>>("/portfolios");
      const items = extractArray<PortfolioItem>(response);
      return { items, total: items.length };
    },
  });

  const { data: activePortfolio, isLoading: loadingDetail } = useQuery({
    queryKey: ["portfolio", selectedId],
    queryFn: () => apiGet<Portfolio>(`/portfolios/${selectedId}`),
    enabled: !!selectedId,
  });

  const createMutation = useMutation({
    mutationFn: (name: string) => apiPost("/portfolios", { 
      name, 
      description: "", 
      initial_capital: 0, 
      currency: "IRR" 
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["portfolios"] });
      toast.success("پرتفوی با موفقیت ایجاد شد");
      setIsCreating(false);
      setNewPortfolioName("");
    },
    onError: (err: Error) => toast.error(err.message || "خطا در ایجاد پرتفوی"),
  });

  return (
    <AppLayout title="مدیریت پرتفوی" subtitle="مانیتورینگ دارایی‌ها و تحلیل سود و زیان">
      <div className="flex items-center justify-between mb-6">
        <button 
          onClick={() => setIsCreating(!isCreating)}
          className="bg-primary-600 hover:bg-primary-500 text-white rounded-lg px-4 py-2 text-sm font-medium transition"
        >
          {isCreating ? "لغو" : "پرتفوی جدید +"}
        </button>
      </div>

      {isCreating && (
        <div className="glass-card p-6 mb-6 animate-in fade-in slide-in-from-top-4">
          <h2 className="font-bold text-surface-200 mb-4">ایجاد پرتفوی جدید</h2>
          <div className="flex gap-3">
            <input 
              type="text" 
              value={newPortfolioName} 
              onChange={(e) => setNewPortfolioName(e.target.value)}
              placeholder="نام پرتفوی (مثلا: بلندمدت، ریسکی...)"
              className="flex-1 px-3 py-2 bg-surface-800 border border-surface-700 rounded text-surface-200 text-sm focus:outline-none focus:border-primary-500"
            />
            <button 
              onClick={() => createMutation.mutate(newPortfolioName)}
              disabled={createMutation.isPending || !newPortfolioName}
              className="px-6 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded text-sm font-medium disabled:opacity-50"
            >
              {createMutation.isPending ? "در حال ثبت..." : "ثبت"}
            </button>
          </div>
        </div>
      )}

      <div className="grid lg:grid-cols-4 gap-6">
        {/* Portfolio List */}
        <div className="lg:col-span-1 space-y-3">
          <h3 className="text-xs font-bold text-surface-500 uppercase tracking-wider mb-3">پرتفوهای من</h3>
          {loadingList ? (
            <div className="space-y-2">
              {[1, 2, 3].map((i) => (
                <div key={i} className="h-16 bg-surface-800 animate-pulse rounded-xl" />
              ))}
            </div>
          ) : portfolios?.items.length ? (
            portfolios.items.map((p: PortfolioItem) => (
              <div 
                key={p.id} 
                onClick={() => setSelectedId(p.id)}
                className={`p-4 rounded-xl cursor-pointer transition-all border ${
                  selectedId === p.id 
                    ? "bg-primary-600/20 border-primary-600 text-primary-100" 
                    : "bg-surface-900/50 border-surface-800 text-surface-400 hover:bg-surface-800"
                }`}
              >
                <div className="font-bold text-sm">{p.name}</div>
                <div className="text-xs opacity-70 mt-1">
                  {p.current_value.toLocaleString()} ریال
                </div>
              </div>
            ))
          ) : (
            <div className="text-xs text-surface-600 text-center py-4">
              پرتفویی یافت نشد
            </div>
          )}
        </div>

        {/* Portfolio Detail */}
        <div className="lg:col-span-3 space-y-6">
          {!selectedId ? (
            <div className="glass-card h-full flex flex-col items-center justify-center text-center p-12">
              <span className="text-4xl mb-4">💼</span>
              <h3 className="text-lg font-bold text-surface-200">پرتفویی انتخاب نشده است</h3>
              <p className="text-sm text-surface-500 mt-2">
                برای مشاهده جزئیات دارایی‌ها، یک پرتفوی را از لیست سمت راست انتخاب کنید.
              </p>
            </div>
          ) : loadingDetail ? (
            <div className="space-y-6">
              <div className="h-32 bg-surface-800 animate-pulse rounded-2xl" />
              <div className="h-64 bg-surface-800 animate-pulse rounded-2xl" />
              <div className="h-96 bg-surface-800 animate-pulse rounded-2xl" />
            </div>
          ) : activePortfolio ? (
            <>
              {/* Stats Summary */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="glass-card p-5">
                  <div className="text-xs text-surface-500 mb-1">ارزش فعلی</div>
                  <div className="text-2xl font-black text-surface-100">
                    {activePortfolio.current_value.toLocaleString()} 
                    <span className="text-xs font-normal"> ریال</span>
                  </div>
                </div>
                <div className="glass-card p-5">
                  <div className="text-xs text-surface-500 mb-1">سرمایه اولیه</div>
                  <div className="text-2xl font-black text-surface-400">
                    {activePortfolio.initial_capital.toLocaleString()} 
                    <span className="text-xs font-normal"> ریال</span>
                  </div>
                </div>
                <div className="glass-card p-5">
                  <div className="text-xs text-surface-500 mb-1">سود/زیان کل</div>
                  <div className={`text-2xl font-black ${
                    activePortfolio.current_value >= activePortfolio.initial_capital 
                      ? "text-accent-emerald" 
                      : "text-accent-rose"
                  }`}>
                    {(activePortfolio.current_value - activePortfolio.initial_capital).toLocaleString()}
                  </div>
                </div>
              </div>

              {/* Equity Curve Chart */}
              <div className="glass-card p-6">
                <h3 className="font-bold text-surface-200 mb-6">نمودار رشد سرمایه (NAV)</h3>
                <EquityCurveChart positions={activePortfolio.positions} />
              </div>

              {/* Positions Table */}
              <div className="glass-card overflow-hidden">
                <div className="p-5 border-b border-surface-800">
                  <h3 className="font-bold text-surface-200">موقعیت‌های فعلی</h3>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-right text-sm">
                    <thead>
                      <tr className="text-surface-500 bg-surface-900/50 border-b border-surface-800">
                        <th className="p-4 font-medium">نماد</th>
                        <th className="p-4 font-medium">تعداد</th>
                        <th className="p-4 font-medium">میانگین خرید</th>
                        <th className="p-4 font-medium">قیمت فعلی</th>
                        <th className="p-4 font-medium">ارزش بازار</th>
                        <th className="p-4 font-medium">سود/زیان</th>
                        <th className="p-4 font-medium">وزن</th>
                      </tr>
                    </thead>
                    <tbody>
                      {activePortfolio.positions.map((pos: Position, index: number) => (
                        <tr 
                          key={index} 
                          className="border-b border-surface-800/50 hover:bg-white/5 transition-colors"
                        >
                          <td className="p-4 font-bold text-surface-200">{pos.symbol}</td>
                          <td className="p-4 font-mono text-surface-400">
                            {pos.quantity.toLocaleString()}
                          </td>
                          <td className="p-4 font-mono text-surface-400">
                            {pos.avg_cost?.toLocaleString()}
                          </td>
                          <td className="p-4 font-mono text-surface-200">
                            {pos.current_price?.toLocaleString()}
                          </td>
                          <td className="p-4 font-mono text-surface-200">
                            {pos.market_value?.toLocaleString()}
                          </td>
                          <td className={`p-4 font-mono ${
                            pos.unrealized_pnl >= 0 ? "text-accent-emerald" : "text-accent-rose"
                          }`}>
                            {pos.unrealized_pnl >= 0 ? "+" : ""}
                            {pos.unrealized_pnl?.toLocaleString()}
                          </td>
                          <td className="p-4">
                            <div className="flex items-center gap-2">
                              <div className="w-12 h-1.5 bg-surface-800 rounded-full overflow-hidden">
                                <div 
                                  className="h-full bg-primary-500" 
                                  style={{ width: `${pos.weight_pct}%` }} 
                                />
                              </div>
                              <span className="text-xs text-surface-500">{pos.weight_pct}%</span>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </>
          ) : (
            <div className="glass-card p-12 text-center text-surface-500">
              اطلاعات پرتفوی یافت نشد
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import { apiGet, apiPut, getStoredAuth } from "@/lib/api";

interface UserProfile {
  id: string;
  username: string;
  email: string;
  full_name: string;
  phone: string;
  roles: string[];
  is_active: boolean;
  is_verified: boolean;
  last_login: string;
  created_at: string;
}

export default function ProfilePage() {
  const auth = getStoredAuth();
  const [formData, setFormData] = useState({ full_name: "", phone: "", email: "" });

  const { data: user, isLoading } = useQuery({
    queryKey: ["user-profile"],
    queryFn: () => apiGet<UserProfile>("/auth/me", auth?.token),
    enabled: !!auth,
  });

  const updateMutation = useMutation({
    mutationFn: (data: Record<string, unknown>) => apiPut("/auth/profile", data, auth?.token),
    onSuccess: () => {
      toast.success("پروفایل با موفقیت به‌روزرسانی شد");
    },
    onError: (err: Error) => toast.error(err.message || "خطا در به‌روزرسانی پروفایل"),
  });

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    updateMutation.mutate(formData);
  };

  if (!auth) return <div className="flex h-screen items-center justify-center text-white bg-[#0a0a14]">لطفا ابتدا وارد حساب خود شوید.</div>;

  return (
    <AppLayout title="پروفایل کاربر" subtitle="مدیریت اطلاعات شخصی و تنظیمات حساب">
        <div className="max-w-3xl mx-auto">
          {isLoading ? (
            <div className="space-y-4">
              <div className="h-64 bg-surface-800 animate-pulse rounded-2xl" />
              <div className="h-32 bg-surface-800 animate-pulse rounded-2xl" />
            </div>
          ) : user ? (
            <div className="space-y-6">
              <div className="glass-card p-6 flex items-center gap-6">
                <div className="w-24 h-24 rounded-full bg-primary-600 flex items-center justify-center text-3xl font-bold text-white">
                  {user.username[0].toUpperCase()}
                </div>
                <div>
                  <h2 className="text-xl font-bold text-surface-100">{user.full_name || user.username}</h2>
                  <p className="text-sm text-surface-400">{user.email}</p>
                  <div className="flex gap-2 mt-2">
                    <span className="text-xs px-2 py-0.5 rounded-full bg-surface-800 text-surface-400">{user.roles.join(", ")}</span>
                    {user.is_verified && <span className="text-xs px-2 py-0.5 rounded-full bg-accent-emerald/15 text-accent-emerald">تایید شده</span>}
                  </div>
                </div>
              </div>

              <form onSubmit={handleSave} className="glass-card p-6 space-y-4">
                <h3 className="font-bold text-surface-200 mb-4">ویرایش اطلاعات</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs text-surface-500 mb-1">نام کامل</label>
                    <input 
                      type="text" 
                      value={formData.full_name} 
                      onChange={(e) => setFormData({...formData, full_name: e.target.value})}
                      className="w-full px-3 py-2 bg-surface-800 border border-surface-700 rounded text-surface-200 text-sm focus:outline-none focus:border-primary-500" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs text-surface-500 mb-1">تلفن</label>
                    <input 
                      type="text" 
                      value={formData.phone} 
                      onChange={(e) => setFormData({...formData, phone: e.target.value})}
                      className="w-full px-3 py-2 bg-surface-800 border border-surface-700 rounded text-surface-200 text-sm focus:outline-none focus:border-primary-500" 
                    />
                  </div>
                  <div className="md:col-span-2">
                    <label className="block text-xs text-surface-500 mb-1">ایمیل</label>
                    <input 
                      type="email" 
                      value={formData.email} 
                      onChange={(e) => setFormData({...formData, email: e.target.value})}
                      className="w-full px-3 py-2 bg-surface-800 border border-surface-700 rounded text-surface-200 text-sm focus:outline-none focus:border-primary-500" 
                    />
                  </div>
                </div>
                <button 
                  type="submit" 
                  disabled={updateMutation.isPending}
                  className="px-6 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded text-sm font-medium transition disabled:opacity-50"
                >
                  {updateMutation.isPending ? "در حال ذخیره..." : "ذخیره تغییرات"}
                </button>
              </form>
            </div>
          ) : (
            <div className="text-center py-12 text-surface-500">اطلاعات کاربر یافت نشد.</div>
          )}
        </div>
    </AppLayout>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import AppLayout from "@/components/layout/AppLayout";
import { Card } from "@/components/ui/Card";
import { apiGet } from "@/lib/api";

interface BacktestRun {
  id: string;
  name: string;
  status: string;
  progress_pct: number;
  message: string;
  completed_at?: string;
}

interface BacktestResult {
  id: string;
  name: string;
  total_return_pct: number;
  sharpe_ratio: number;
  max_drawdown_pct: number;
  win_rate: number;
  total_trades: number;
  final_value: number;
  initial_capital: number;
}

export default function ResultsPage() {
  const [selectedRun, setSelectedRun] = useState<string | null>(null);

  const { data: runs, isLoading: loadingRuns } = useQuery({
    queryKey: ["backtest-runs"],
    queryFn: () => apiGet<BacktestRun[]>( "/backtests/runs"),
  });

  const { data: result, isLoading: loadingResult } = useQuery({
    queryKey: ["backtest-result", selectedRun],
    queryFn: () => apiGet<BacktestResult>( `/backtests/runs/${selectedRun}/result`),
    enabled: !!selectedRun,
  });

  return (
    <AppLayout title="مرکز نتایج و گزارشات" subtitle="بررسی عملکرد استراتژی‌ها و خروجی‌های شبیه‌سازی">
      <div className="grid lg:grid-cols-3 gap-6">
          {/* Runs List */}
          <div className="lg:col-span-1 space-y-3">
            <h3 className="text-xs font-bold text-surface-500 uppercase tracking-wider mb-3">تاریخچه اجراها</h3>
            {loadingRuns ? (
              <div className="space-y-2">
                {[1,2,3,4,5].map(i => <div key={i} className="h-16 bg-surface-800 animate-pulse rounded-xl" />)}
              </div>
            ) : runs?.map(run => (
              <div 
                key={run.id} 
                onClick={() => setSelectedRun(run.id)}
                className={`p-4 rounded-xl cursor-pointer transition-all border ${
                  selectedRun === run.id ? "bg-primary-600/20 border-primary-600 text-primary-100" : "bg-surface-900/50 border-surface-800 text-surface-400 hover:bg-surface-800"
                }`}
              >
                <div className="flex justify-between items-start mb-1">
                  <div className="font-bold text-sm truncate">{run.name}</div>
                  <span className={`text-[10px] px-1.5 py-0.5 rounded ${
                    run.status === "completed" ? "bg-emerald-500/20 text-emerald-400" : "bg-amber-500/20 text-amber-400"
                  }`}>
                    {run.status === "completed" ? "کامل" : "در جریان"}
                  </span>
                </div>
                <div className="text-xs opacity-60 truncate">{run.message}</div>
                {run.status === "completed" && (
                   <div className="mt-2 h-1 bg-surface-800 rounded-full overflow-hidden">
                     <div className="h-full bg-primary-500" style={{ width: `${run.progress_pct}%` }} />
                   </div>
                )}
              </div>
            )) || <div className="text-xs text-surface-600 text-center py-4">هیچ اجرای ثبت شده‌ای یافت نشد</div>}
          </div>

          {/* Result Detail */}
          <div className="lg:col-span-2 space-y-6">
            {!selectedRun ? (
              <div className="glass-card h-full flex flex-col items-center justify-center text-center p-12">
                <span className="text-4xl mb-4">📈</span>
                <h3 className="text-lg font-bold text-surface-200">نتیجه‌ای برای نمایش نیست</h3>
                <p className="text-sm text-surface-500 mt-2">یک اجرای بک‌تست را از لیست سمت راست انتخاب کنید تا تحلیل دقیق آن را مشاهده کنید.</p>
              </div>
            ) : loadingResult ? (
              <div className="space-y-6">
                <div className="h-32 bg-surface-800 animate-pulse rounded-2xl" />
                <div className="h-64 bg-surface-800 animate-pulse rounded-2xl" />
              </div>
            ) : result ? (
              <>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  {[
                    { label: "بازده کل", value: `${result.total_return_pct}%`, color: result.total_return_pct >= 0 ? "text-accent-emerald" : "text-accent-rose" },
                    { label: "نسبت شارپ", value: result.sharpe_ratio.toFixed(2), color: result.sharpe_ratio >= 1 ? "text-accent-emerald" : "text-accent-amber" },
                    { label: "بیشترین کاهش", value: `${result.max_drawdown_pct}%`, color: "text-accent-rose" },
                    { label: "نرخ برد", value: `${result.win_rate}%`, color: "text-accent-cyan" },
                  ].map((stat, i) => (
                    <div key={i} className="glass-card p-4 text-center">
                      <div className="text-xs text-surface-500 mb-1">{stat.label}</div>
                      <div className={`text-xl font-black ${stat.color}`}>{stat.value}</div>
                    </div>
                  ))}
                </div>

