import { useEffect, useState, useRef, type ReactNode } from "react";

interface ChartContainerProps {
  children: ReactNode;
  height: number;
  className?: string;
}

/**
 * Wraps a Recharts ResponsiveContainer to prevent the
 * "width/height are less than the minimum" warning that occurs
 * during SSR / first paint when the DOM container isn't laid out yet.
 *
 * Usage:
 *   <ChartContainer height={250}>
 *     <ResponsiveContainer width="100%" height="100%">…</ResponsiveContainer>
 *   </ChartContainer>
 */
export default function ChartContainer({
  children,
  height,
  className = "",
}: ChartContainerProps) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    // RequestAnimationFrame guarantees the parent has been laid out and
    // measurements are available.  A simple `setMounted(true)` in the
    // effect is enough for almost all cases — rAF just adds a safety
    // margin for edge cases where layout is deferred (tabs, modals, …).
    const raf = requestAnimationFrame(() => setMounted(true));
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <div
      className={className}
      style={{ width: "100%", height, position: "relative" }}
    >
      {mounted ? (
        children
      ) : (
        /* Placeholder with same dimensions so layout doesn't shift. */
        <div style={{ width: "100%", height: "100%" }} />
      )}
    </div>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { apiGet, extractArray } from "@/lib/api";
import { MarketIndex, generateMockIndices } from "@/lib/types";

function IndexCard({ idx }: { idx: MarketIndex }) {
  return (
    <div className="index-card">
      <div className="index-icon">
        <span className="material-icons text-xl">{idx.icon}</span>
      </div>
      <div className="index-info">
        <span className="index-name">{idx.name}</span>
        <span className="index-value">{idx.value}</span>
        <span className={`index-change ${idx.isUp ? "positive" : "negative"}`}>
          <span className="material-icons text-xs">{idx.isUp ? "arrow_upward" : "arrow_downward"}</span>
          {Math.abs(idx.changePercent).toFixed(2)}%
        </span>
      </div>
    </div>
  );
}

export default function MarketIndices() {
  const { data: indices } = useQuery({
    queryKey: ["market-indices"],
    queryFn: async () => {
      try {
        // Backend: GET /market/overview returns ApiResponse<{ indices: [...], ... }>
        const res = await apiGet<Record<string, unknown>>("/market/overview");
        // Extract indices from various possible response shapes
        if (res?.indices) return res.indices;
        if (res?.markets) return res.markets;
        if (Array.isArray(res)) return res;
        // Try to find any array in the response
        for (const key of ["items", "data", "result"]) {
          if (res?.[key] && Array.isArray(res[key])) return res[key];
        }
      } catch {
        // Backend unavailable — use mock data
      }
      return generateMockIndices();
    },
    refetchInterval: 30000,
    staleTime: 10000,
  });

  return (
    <div className="market-indices">
      {indices?.map((idx: MarketIndex, i: number) => (
        <IndexCard key={i} idx={idx} />
      ))}
    </div>
  );
}

